#!/usr/bin/env python3
"""Generate internal Markdown and HTML summary from appended benchmark CSV records."""
import csv, html, math, statistics
from collections import defaultdict
from pathlib import Path
from ops_common import ROOT

CSV = ROOT / "llm_benchmark_results.csv"
def num(v):
    try: return float(v)
    except (TypeError, ValueError): return None
def pct(values, q):
    if not values: return None
    values = sorted(values); pos = (len(values)-1)*q; lo, hi = int(pos), math.ceil(pos)
    return values[lo] if lo == hi else values[lo] + (values[hi]-values[lo])*(pos-lo)
def fmt(v, suffix=""):
    return "n/a" if v is None else f"{v:.2f}{suffix}"
def table(headers, data):
    return "| " + " | ".join(headers) + " |\n|" + "|".join(["---"]*len(headers)) + "|\n" + "\n".join("| " + " | ".join(map(str,row)) + " |" for row in data)
def main():
    if not CSV.exists() or CSV.stat().st_size == 0: raise SystemExit("No benchmark CSV found; run llm_benchmark.py first.")
    with CSV.open(newline="") as f: rows = list(csv.DictReader(f))
    if not rows: raise SystemExit("Benchmark CSV has no records.")
    good = [r for r in rows if r["success"].lower() == "true"]; lat = [num(r["total_latency_seconds"]) for r in good if num(r["total_latency_seconds"]) is not None]
    by_alias = defaultdict(list); by_concurrency = defaultdict(list)
    for r in rows: by_alias[r["model_alias"]].append(r); by_concurrency[r["concurrency"]].append(r)
    def summary(group):
        ok = [r for r in group if r["success"].lower()=="true"]; ls=[num(r["total_latency_seconds"]) for r in ok if num(r["total_latency_seconds"]) is not None]; ts=[num(r["tokens_per_second"]) for r in ok if num(r["tokens_per_second"]) is not None]
        return len(group), len(ok), 100*len(ok)/len(group) if group else 0, statistics.mean(ls) if ls else None, pct(ls,.5), pct(ls,.95), statistics.mean(ts) if ts else None
    model_rows = [[alias, *[fmt(x,"%") if i==2 else fmt(x," s") if i in (3,4,5) else fmt(x," tok/s") if i==6 else x for i,x in enumerate(summary(group))]] for alias,group in sorted(by_alias.items())]
    conc_rows = [[c, *[fmt(x,"%") if i==2 else fmt(x," s") if i in (3,4,5) else fmt(x," tok/s") if i==6 else x for i,x in enumerate(summary(group))]] for c,group in sorted(by_concurrency.items(), key=lambda x:int(x[0]))]
    slow = sorted(good, key=lambda r:num(r["total_latency_seconds"]) or -1, reverse=True)[:10]; fast = sorted(good, key=lambda r:num(r["total_latency_seconds"]) or float("inf"))[:10]
    def obs(field_before, field_after):
        pairs=[(num(r[field_before]),num(r[field_after])) for r in good]; deltas=[b-a for a,b in pairs if a is not None and b is not None]
        return f"{max(deltas):.1f}" if deltas else "n/a"
    flags = {k:sum(r.get(k,"" ).lower()=="true" for r in rows) for k in ("switched_language","contains_fake_tool_json","includes_mermaid_expected","refused_warned_expected","looks_truncated")}
    lines = ["# Local LLM benchmark report", "", "## Executive summary", "", "Benchmarked a self-hosted local LLM deployment across latency, throughput, memory usage and concurrent-user workloads to estimate safe serving limits.", "", f"This report contains {len(rows)} requests: {len(good)} successful ({100*len(good)/len(rows):.1f}%) and {len(rows)-len(good)} failed ({100*(len(rows)-len(good))/len(rows):.1f}%). Aggregate successful-request latency: p50 {fmt(pct(lat,.5),' s')}, p95 {fmt(pct(lat,.95),' s')}, mean {fmt(statistics.mean(lat) if lat else None,' s')}. Results are workload-specific, not production capacity guarantees.", "", "## Architecture", "", "Users → Open WebUI → LiteLLM → Ollama → Local Models → P100 GPU.", "", "## Tested models", "", table(["Alias","Requests","Successful","Success rate","Mean latency","p50","p95","Mean tok/s"],model_rows), "", "## Concurrency comparison", "", table(["Concurrency","Requests","Successful","Success rate","Mean latency","p50","p95","Mean tok/s"],conc_rows), "", "## Fastest successful requests", "", table(["Alias","Scenario","Latency","Prompt words"], [[r['model_alias'],r['test_name'],fmt(num(r['total_latency_seconds']),' s'),r['prompt_words']] for r in fast]), "", "## Slowest successful requests", "", table(["Alias","Scenario","Latency","Prompt words"], [[r['model_alias'],r['test_name'],fmt(num(r['total_latency_seconds']),' s'),r['prompt_words']] for r in slow]), "", "## Resource observations", "", f"Largest observed per-request end-minus-start VRAM change: {obs('gpu_vram_mib_before','gpu_vram_mib_after')} MiB. GPU samples are point-in-time snapshots and may miss peak utilisation. Largest observed RAM change: {obs('ram_used_mib_before','ram_used_mib_after')} MiB. CPU load and RAM values are also snapshots; use trends for capacity decisions.", "", "## Evaluation observations", "", f"Language-switch flags: {flags['switched_language']}; fake tool/function JSON flags: {flags['contains_fake_tool_json']}; Mermaid-present flags: {flags['includes_mermaid_expected']}; refusal/warning flags: {flags['refused_warned_expected']}; truncation flags: {flags['looks_truncated']}. These are lightweight heuristics, not a safety certification or a complete quality assessment.", "", "## Recommended serving limits", "", "Start normal operation at one active generation per P100 and admit a second request only as queued or controlled concurrency. The current Ollama setting already limits loaded models to one and parallel work to two. Do not infer readiness for three or more simultaneous users from a quick run; rerun a representative bounded benchmark after any model, context, quantisation or gateway-profile change. Set user expectations for queueing and enforce request timeouts.", "", "## Method and limitations", "", "The benchmark uses the local OpenAI-compatible LiteLLM chat endpoint, fixed temperature 0, streaming when available, and no more than concurrency 3. Time to first token measures first streamed content received. Tokens/sec is completion tokens divided by full request duration, so it includes queueing, prompt work and model loading. Records append across runs; filter by run_id for a single run. Review response previews/full JSONL before sharing internally."]
    md="\n".join(lines)+"\n"; (ROOT/"benchmark_report.md").write_text(md)
    def htable(headers, data):
        return "<table><thead><tr>" + "".join(f"<th>{html.escape(str(x))}</th>" for x in headers) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{html.escape(str(x))}</td>" for x in row) + "</tr>" for row in data) + "</tbody></table>"
    overview = f"<p>{len(rows)} requests · <strong>{len(good)} successful ({100*len(good)/len(rows):.1f}%)</strong> · p50 {fmt(pct(lat,.5),' s')} · p95 {fmt(pct(lat,.95),' s')} · mean {fmt(statistics.mean(lat) if lat else None,' s')}</p>"
    page = "<!doctype html><html><head><meta charset='utf-8'><title>Local LLM benchmark report</title><style>body{font:16px system-ui,sans-serif;max-width:1120px;margin:40px auto;padding:0 24px;color:#1d2939;line-height:1.5}h1{color:#0b4f6c;margin-bottom:0}.lead{color:#475467}table{border-collapse:collapse;width:100%;margin:14px 0 28px}th{text-align:left;background:#eaf4f7}th,td{padding:8px;border:1px solid #d0d5dd}section{margin:30px 0}.note{background:#fff8e6;padding:14px;border-left:4px solid #eaaa08}</style></head><body>" + f"<h1>Local LLM benchmark report</h1><p class='lead'>Internal operational assessment · generated from {html.escape(CSV.name)}</p><section><h2>Executive summary</h2><p>Benchmarked a self-hosted local LLM deployment across latency, throughput, memory usage and concurrent-user workloads to estimate safe serving limits.</p>{overview}</section><section><h2>Architecture</h2><p>Users → Open WebUI → LiteLLM → Ollama → Local Models → P100 GPU.</p></section><section><h2>Tested models</h2>" + htable(["Alias","Requests","Successful","Success rate","Mean latency","p50","p95","Mean tok/s"], model_rows) + "</section><section><h2>Concurrency comparison</h2>" + htable(["Concurrency","Requests","Successful","Success rate","Mean latency","p50","p95","Mean tok/s"], conc_rows) + "</section><section><h2>Fastest requests</h2>" + htable(["Alias","Scenario","Latency","Prompt words"], [[r['model_alias'],r['test_name'],fmt(num(r['total_latency_seconds']),' s'),r['prompt_words']] for r in fast]) + "</section><section><h2>Slowest requests</h2>" + htable(["Alias","Scenario","Latency","Prompt words"], [[r['model_alias'],r['test_name'],fmt(num(r['total_latency_seconds']),' s'),r['prompt_words']] for r in slow]) + f"</section><section><h2>Resource and evaluation observations</h2><p>Largest observed per-request VRAM change: {obs('gpu_vram_mib_before','gpu_vram_mib_after')} MiB; RAM change: {obs('ram_used_mib_before','ram_used_mib_after')} MiB. GPU/RAM/CPU values are point-in-time samples and may miss peaks.</p><p>Language switch flags: {flags['switched_language']}; fake tool/function JSON: {flags['contains_fake_tool_json']}; Mermaid flags: {flags['includes_mermaid_expected']}; refusal/warning flags: {flags['refused_warned_expected']}; truncation flags: {flags['looks_truncated']}.</p></section><section class='note'><h2>Recommended serving limits</h2><p>Start with one active generation per P100 and admit a second request only as queued or controlled concurrency. Do not infer readiness for three or more simultaneous users from a quick run; rerun a representative bounded benchmark after model/profile changes.</p></section></body></html>"
    (ROOT/"benchmark_report.html").write_text(page)
    print(f"Wrote benchmark_report.md and benchmark_report.html from {len(rows)} record(s).")
if __name__ == "__main__": main()
